export function random(bytes) {
  // `|=` convert `bytes` to number to prevent `valueOf` abusing
  bytes |= 0
  if (bytes < 0) throw new RangeError('Wrong ID size')
  // `random()` is used rarely and not in hot paths, so it makes
  // a direct crypto call instead of using a byte pool.
  let buffer = Buffer.allocUnsafe(bytes)
  fillRandom(buffer)
  return buffer
}

function fillRandom(buffer) {
  let from = 0
  while (from < buffer.length) {
    let to = Math.min(from + GET_RANDOM_LIMIT, buffer.length)
    crypto.getRandomValues(buffer.subarray(from, to))
    from = to
  }
}

describe('random', () => {
  test(`throws on negative size`, () => {
    throws(() => {
      random(-1)
    }, /Wrong ID size|Invalid typed array length/)
  })

  test(`generates small random buffers`, () => {
    for (let i = 0; i < urlAlphabet.length; i++) {
      equal(random(10).length, 10)
    }
  })

  test(`generates random buffers`, () => {
    let numbers = {}
    let bytes = random(1000)
    equal(bytes.length, 1000)
    for (let byte of bytes) {
      if (!numbers[byte]) numbers[byte] = 0
      numbers[byte] += 1
      equal(typeof byte, 'number')
      ok(byte <= 255)
      ok(byte >= 0)
    }
  })
})

  } else {
    // Rejection sampling accepts `alphabetLen` of every `mask + 1`
    // random bytes. `1.6` requests extra bytes to cover
    // unlucky streaks in most fills.
    let randomBytes = Buffer.allocUnsafe(
      Math.ceil((1.6 * (mask + 1) * target) / alphabetLen)
    )
    let accepted = 0
    while (accepted < target) {
      fillRandom(randomBytes)
      for (let i = 0; i < randomBytes.length; i++) {
        let index = randomBytes[i] & mask
        if (index < alphabetLen) {
          buffer[accepted++] = charCodes[index]
          if (accepted === target) break
        }
      }
    }
  }
  pool = buffer.toString('latin1')
  poolOffset = 0
}

### 사용자 지정 랜덤 바이트 생성기

`customRandom` 함수를 사용하면 `nanoid`에서 사용할 문자열과 알고리즘을 지정할 수 있습니다.

아래 예시는 시드 값을 기반으로 하는 랜덤 생성기를 사용하였습니다.

```js
import { customRandom } from "nanoid";

const rng = seedrandom(seed);
const nanoid = customRandom("abcdef", 10, (size) => {
  return new Uint8Array(size).map(() => 256 * rng());
});

nanoid(); //=> "fbaefaadeb"
```

콜백 함수 `random` 는 반드시 배열의 크기를 받을 수 있어야 하며, 랜덤 숫자로 이루어진 배열을 리턴해야 합니다.

{
  "name": "@sitnik/nanoid",
  "version": "6.0.1",
  "license": "MIT",
  "exports": {
    ".": "./index.browser.js",
    "./non-secure": "./non-secure/index.js"
  },
  "publish": {
    "include": [
      "LICENSE",
      "README.md",
      "index.d.ts",
      "index.browser.js",
      "non-secure/index.d.ts",
      "non-secure/index.js",
      "url-alphabet/index.js"
    ]
  }
}

### 自定义随机字节生成器

`customRandom` 允许您创建一个 `nanoid` 并替换字母表
和默认的随机字节生成器。

在此示例中，使用基于种子的生成器:

```js
import { customRandom } from "nanoid";

const rng = seedrandom(seed);
const nanoid = customRandom("abcdef", 10, (size) => {
  return new Uint8Array(size).map(() => 256 * rng());
});

nanoid(); //=> "fbaefaadeb"
```

`random` 回调必须接受数组大小并返回随机数的数组。

如果要使用与 `customRandom` 相同的URL友好符号,
您可以使用 `urlAlphabet` 获取默认字母表。

```js
const { customRandom, urlAlphabet } = require("nanoid");
const nanoid = customRandom(urlAlphabet, 10, random);
```

### Generasi Random Bytes (Custom)

`customRandom` digunakan untuk membuat Nano ID yang mengganti alfabet dan algoritma _random bytes generator_ yang telah diimplementasikan pada versi bawaan (dalam artian menggunakan algoritma sendiri untuk mendapatkan random bytes).

Pada contoh berikut, digunakan _seed-based generator_:

```js
import { customRandom } from "nanoid";

const rng = seedrandom(seed);
const nanoid = customRandom("abcdef", 10, (size) => {
  return new Uint8Array(size).map(() => 256 * rng());
});

nanoid(); //=> "fbaefaadeb"
```

Fungsi _callback_ pada `random` harus menerima ukuran array dan mengembalikan sebuah array dengan angka acak.

